import type { HumanRigMapping } from '../HumanRig.ts';

/**
 * Mapping for the Rigify (Blender) **metarig**, that is, when the mesh is weighted directly to the bones
 * of the metarig (`spine`, `thigh.L`, …) and not to the generated rig.
 *
 * The rig generated by Rigify (`DEF-*`, with intermediate twist bones such as `DEF-thigh.L.001`) is not a
 * direct leg chain and doesn't work as is.
 *
 * You can use the Blender names (with a dot) or the ones GLTFLoader leaves (without the dot, `thighL`):
 * the mapper accepts both forms.
 *
 * Twist bones (optional, not part of the metarig): `thigh_twist.L`, `shin_twist.L`, `upper_arm_twist.L`,
 * `forearm_twist.L` (and `.R`), children of the segment and outside the chain.
 * See docs/en/skeletons.md.
 */
export const rigifyMapping: HumanRigMapping = {
  hips: 'spine',
  left: { thigh: 'thigh.L', shin: 'shin.L', foot: 'foot.L', toe: 'toe.L', thighTwist: 'thigh_twist.L', shinTwist: 'shin_twist.L' },
  right: { thigh: 'thigh.R', shin: 'shin.R', foot: 'foot.R', toe: 'toe.R', thighTwist: 'thigh_twist.R', shinTwist: 'shin_twist.R' },
  spine: 'spine.001',
  chest: 'spine.003',
  neck: 'spine.004',
  head: 'spine.006',
  leftArm: {
    shoulder: 'shoulder.L',
    upperArm: 'upper_arm.L',
    forearm: 'forearm.L',
    hand: 'hand.L',
    upperArmTwist: 'upper_arm_twist.L',
    forearmTwist: 'forearm_twist.L',
    fingers: {
      thumb: ['thumb.01.L', 'thumb.02.L', 'thumb.03.L'],
      index: ['f_index.01.L', 'f_index.02.L', 'f_index.03.L'],
      middle: ['f_middle.01.L', 'f_middle.02.L', 'f_middle.03.L'],
      ring: ['f_ring.01.L', 'f_ring.02.L', 'f_ring.03.L'],
      pinky: ['f_pinky.01.L', 'f_pinky.02.L', 'f_pinky.03.L'],
    },
  },
  rightArm: {
    shoulder: 'shoulder.R',
    upperArm: 'upper_arm.R',
    forearm: 'forearm.R',
    hand: 'hand.R',
    upperArmTwist: 'upper_arm_twist.R',
    forearmTwist: 'forearm_twist.R',
    fingers: {
      thumb: ['thumb.01.R', 'thumb.02.R', 'thumb.03.R'],
      index: ['f_index.01.R', 'f_index.02.R', 'f_index.03.R'],
      middle: ['f_middle.01.R', 'f_middle.02.R', 'f_middle.03.R'],
      ring: ['f_ring.01.R', 'f_ring.02.R', 'f_ring.03.R'],
      pinky: ['f_pinky.01.R', 'f_pinky.02.R', 'f_pinky.03.R'],
    },
  },
};
